// ─── Pixel Wires daily digest: settings ──────────────────────────────────────
// Edit the values in CONFIG, save, then use "Execute workflow" to test.
const CONFIG = {
  // WhatsApp number that receives the digest: country code + number, digits only.
  // Example for India: 919876543210
  whatsappTo: '',
  // OpenWA session id: OpenWA dashboard (http://localhost:2785) → Sessions.
  openwaSessionId: '',

  // Services as seen from inside the n8n Docker container.
  openwaUrl: 'http://host.docker.internal:2785',
  ollamaUrl: 'http://host.docker.internal:11434',

  // Where the digest is published. Vercel redeploys on every push to this branch.
  githubOwner: 'ezabhishek',
  githubRepo: 'pixelwire',
  githubBranch: 'main',
  siteUrl: 'https://pixelwire.vercel.app',

  models: {
    score: 'qwen3.5:4b', // rates and tags every fetched post (fast, many calls)
    summary: 'qwen3:8b', // summarizes the shortlisted posts
    editor: 'gemma4:12b', // picks the final list and writes the intro (one call)
  },

  postsPerSource: 30, // fetched from each of DEV and Hacker News
  minScore: 6, // quality score (1-10) needed to reach the shortlist
  maxCandidates: 20, // shortlist size sent for summaries
  topN: 10, // posts in the published digest
  postsInWhatsApp: 5, // posts listed in the WhatsApp message
};
// ──────────────────────────────────────────────────────────────────────────────

const problems = [];
if (!/^\d{8,15}$/.test(CONFIG.whatsappTo)) {
  problems.push('whatsappTo must be your number with country code, digits only (for example 919876543210)');
}
if (!CONFIG.openwaSessionId || CONFIG.openwaSessionId.startsWith('__')) {
  problems.push('openwaSessionId is empty; copy it from the OpenWA dashboard');
}
if (CONFIG.topN > CONFIG.maxCandidates) problems.push('topN cannot be larger than maxCandidates');
if (problems.length > 0) throw new Error(`Config: ${problems.join('; ')}`);

// $now uses the workflow timezone (Asia/Kolkata), so the date matches the 07:00 run.
return [
  {
    json: {
      ...CONFIG,
      date: $now.toFormat('yyyy-MM-dd'),
      dateLabel: $now.toFormat('cccc, d LLLL yyyy'),
      startedAt: $now.toISO(),
    },
  },
];

// Turn DEV and Hacker News results into the Article shape the website uses
// (src/types/article.ts), and drop duplicates that link to the same page.

function decodeEntities(text) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' };
  return String(text).replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, code) => {
    if (code[0] === '#') {
      const value = code[1] === 'x' || code[1] === 'X' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      return Number.isFinite(value) && value > 0 && value <= 0x10ffff ? String.fromCodePoint(value) : match;
    }
    return named[code.toLowerCase()] ?? match;
  });
}

// n8n's Code sandbox has no URL global, so parse with regexes.
function domainOf(url) {
  const match = /^https?:\/\/([^/?#:]+)/i.exec(url ?? '');
  return match ? match[1].toLowerCase().replace(/^www\./, '') : null;
}

function urlKey(url) {
  const match = /^https?:\/\/([^/?#]+)([^?#]*)/i.exec(url ?? '');
  return match ? `${match[1].replace(/^www\./i, '')}${match[2].replace(/\/+$/, '')}`.toLowerCase() : String(url);
}

const posts = [];

for (const { json: a } of $('Fetch DEV top posts').all()) {
  if (!a || typeof a.id !== 'number' || !a.title || !a.url) continue;
  const tagList = Array.isArray(a.tag_list) ? a.tag_list : String(a.tag_list ?? '').split(',');
  const username = a.user?.username ?? 'unknown';
  posts.push({
    id: `devto:${a.id}`,
    source: 'devto',
    nativeId: String(a.id),
    title: decodeEntities(a.title.trim()),
    summary: a.description ? decodeEntities(a.description.trim()) || null : null,
    url: a.url,
    domain: 'dev.to',
    discussionUrl: `${a.url}#comments`,
    coverImage: a.cover_image || null,
    tags: [...new Set(tagList.map((t) => t.trim().toLowerCase().replace(/[^a-z0-9]/g, '')).filter(Boolean))],
    author: {
      name: a.user?.name?.trim() || username,
      handle: username,
      avatarUrl: a.user?.profile_image_90 || undefined,
      profileUrl: `https://dev.to/${username}`,
    },
    publishedAt: a.published_timestamp ?? a.published_at ?? new Date().toISOString(),
    readingTimeMinutes: a.reading_time_minutes ?? null,
    score: a.public_reactions_count ?? a.positive_reactions_count ?? 0,
    commentCount: a.comments_count ?? 0,
  });
}

const hn = $('Fetch HN front page').first()?.json;
for (const h of hn?.hits ?? []) {
  const title = h.title?.trim();
  if (!title || !h.objectID) continue;
  const discussionUrl = `https://news.ycombinator.com/item?id=${h.objectID}`;
  const external = h.url?.trim() || null;
  posts.push({
    id: `hackernews:${h.objectID}`,
    source: 'hackernews',
    nativeId: String(h.objectID),
    title: decodeEntities(title),
    summary: null,
    url: external ?? discussionUrl,
    domain: external ? domainOf(external) : 'news.ycombinator.com',
    discussionUrl,
    coverImage: null,
    tags: [],
    author: {
      name: h.author,
      handle: h.author,
      profileUrl: `https://news.ycombinator.com/user?id=${encodeURIComponent(h.author)}`,
    },
    publishedAt: h.created_at,
    readingTimeMinutes: null,
    score: h.points ?? 0,
    commentCount: h.num_comments ?? 0,
  });
}

const seen = new Set();
const unique = posts.filter((post) => {
  const key = urlKey(post.url);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

if (unique.length === 0) {
  throw new Error('No posts were fetched from DEV or Hacker News. Check the two fetch nodes for errors.');
}

return unique.map((post) => ({ json: post }));

// One Ollama request per post: a 1-10 quality score, up to three tags and a short reason.
const cfg = $('Config').first().json;

// Same tag list as the website's sidebar (generated from src/lib/tags.ts).
const TAGS = ["ai","machinelearning","javascript","typescript","react","node","css","webdev","python","rust","go","java","devops","kubernetes","docker","cloud","security","database","linux","opensource","programming","career"];

const SYSTEM = `You are the editor of a daily news digest for professional software developers.
You rate one post at a time and answer only with JSON.

Scoring guide:
9-10: news or deep technical content most developers should see: major releases, security incidents, notable research, excellent in-depth tutorials.
7-8: solid and useful or interesting for many developers.
5-6: niche but legitimate.
3-4: thin or generic: beginner listicles, opinion without substance, marketing-heavy posts.
1-2: spam, crypto or trading promotion, ads, clickbait, off-topic.

Use the whole range. On a typical day only a handful of posts deserve 9 or 10; most solid posts are 6-8.
Judge the substance, not the popularity numbers. Tags must come from the allowed list; use none if nothing fits.`;

const SCHEMA = {
  type: 'object',
  properties: {
    score: { type: 'integer', minimum: 1, maximum: 10 },
    tags: { type: 'array', items: { type: 'string', enum: TAGS }, maxItems: 3 },
    reason: { type: 'string', maxLength: 160 },
  },
  required: ['score', 'tags', 'reason'],
};

function describe(post) {
  const source = post.source === 'devto' ? 'DEV Community (developer blog platform)' : 'Hacker News (link aggregator)';
  const lines = [
    `Title: ${post.title}`,
    `Source: ${source}`,
    `Site: ${post.domain ?? 'unknown'}`,
  ];
  if (post.tags.length > 0) lines.push(`Author's tags: ${post.tags.join(', ')}`);
  if (post.summary) lines.push(`Description: ${post.summary.slice(0, 400)}`);
  lines.push(`Popularity: ${post.score} ${post.source === 'devto' ? 'reactions' : 'points'}, ${post.commentCount} comments`);
  lines.push(`Allowed tags: ${TAGS.join(', ')}`);
  return lines.join('\n');
}

return $input.all().map(({ json: post }) => ({
  json: {
    post,
    request: {
      model: cfg.models.score,
      stream: false,
      think: false,
      keep_alive: '5m',
      format: SCHEMA,
      options: { temperature: 0.1, num_ctx: 4096 },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: describe(post) },
      ],
    },
  },
}));

// Combine each post with its score, then keep the best ones for summarizing.
const cfg = $('Config').first().json;
const requests = $('Build scoring requests').all();
const responses = $input.all();

function parseModelJson(item) {
  try {
    return JSON.parse(item?.json?.message?.content ?? '');
  } catch {
    return null;
  }
}

const scored = requests.map((request, index) => {
  const post = request.json.post;
  const result = parseModelJson(responses[index]);
  const quality = Number.isInteger(result?.score) ? Math.min(10, Math.max(1, result.score)) : 0;
  const modelTags = Array.isArray(result?.tags) ? result.tags.filter((tag) => typeof tag === 'string') : [];
  return {
    ...post,
    // HN posts have no tags of their own; DEV posts keep the author's tags.
    tags: post.source === 'hackernews' ? [...new Set(modelTags)] : post.tags,
    quality,
    qualityReason: typeof result?.reason === 'string' ? result.reason : null,
  };
});

const failed = scored.filter((post) => post.quality === 0).length;
if (failed === scored.length) {
  throw new Error(`Scoring failed for every post. Is Ollama running, and is "${cfg.models.score}" pulled?`);
}

const engagement = (post) => post.score + post.commentCount;
const ranked = [...scored].sort((a, b) => b.quality - a.quality || engagement(b) - engagement(a));

let shortlist = ranked.filter((post) => post.quality >= cfg.minScore).slice(0, cfg.maxCandidates);
if (shortlist.length < cfg.topN) {
  // A slow news day: fill up with the next best so the digest still has topN posts.
  shortlist = ranked.filter((post) => post.quality > 0).slice(0, cfg.topN);
}

return shortlist.map((post) => ({ json: { ...post, scoringFailures: failed, fetchedCount: scored.length } }));

// Extract readable text from each shortlisted page and ask for a two-sentence summary.
const cfg = $('Config').first().json;
const candidates = $('Pick candidates').all();
const pages = $input.all();
const MAX_TEXT = 5000;

function decodeEntities(text) {
  const named = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', hellip: '…', mdash: '—', ndash: '–' };
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, code) => {
    if (code[0] === '#') {
      const value = code[1] === 'x' || code[1] === 'X' ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      return Number.isFinite(value) && value > 0 && value <= 0x10ffff ? String.fromCodePoint(value) : match;
    }
    return named[code.toLowerCase()] ?? match;
  });
}

function extractText(html) {
  if (typeof html !== 'string' || html.length === 0) return '';
  let body = html;
  const main = body.match(/<article[\s\S]*?<\/article>/i) ?? body.match(/<main[\s\S]*?<\/main>/i);
  if (main) body = main[0];
  body = body
    .replace(/<(script|style|noscript|svg|nav|header|footer|form|aside|iframe)\b[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>|<\/(p|div|li|h[1-6]|pre|blockquote|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ');
  return decodeEntities(body)
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/\s*\n\s*/g, '\n')
    .replace(/\n{2,}/g, '\n')
    .trim()
    .slice(0, MAX_TEXT);
}

const SYSTEM = `You write entries for a daily news digest for professional software developers.
Write exactly two plain sentences (at most 60 words) saying what the post is about and why a developer might care.
Use only facts from the provided text. If the article text is missing or thin, describe what the link covers based on the title and site, without inventing details.
No hype, no emojis, no markdown, and do not start with "This article" or "The post".`;

const SCHEMA = {
  type: 'object',
  properties: { summary: { type: 'string', maxLength: 420 } },
  required: ['summary'],
};

return candidates.map(({ json: post }, index) => {
  const text = extractText(pages[index]?.json?.data);
  const userLines = [
    `Title: ${post.title}`,
    `Source: ${post.source === 'devto' ? 'DEV Community' : 'Hacker News'}`,
    `Site: ${post.domain ?? 'unknown'}`,
  ];
  if (post.summary) userLines.push(`Description: ${post.summary}`);
  userLines.push(text.length >= 200 ? `Article text:\n${text}` : 'Article text: (not available)');

  return {
    json: {
      post: { ...post, extractedChars: text.length },
      request: {
        model: cfg.models.summary,
        stream: false,
        think: false,
        keep_alive: '5m',
        format: SCHEMA,
        options: { temperature: 0.3, num_ctx: 8192 },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: userLines.join('\n') },
        ],
      },
    },
  };
});

// Attach summaries to the shortlist and build the single request for the editor model.
const cfg = $('Config').first().json;
const requests = $('Build summary requests').all();
const responses = $input.all();

function parseModelJson(item) {
  try {
    return JSON.parse(item?.json?.message?.content ?? '');
  } catch {
    return null;
  }
}

const candidates = requests.map(({ json }, index) => {
  const result = parseModelJson(responses[index]);
  const generated = typeof result?.summary === 'string' ? result.summary.trim() : '';
  return {
    ...json.post,
    digestSummary: generated || json.post.summary || json.post.qualityReason || json.post.title,
    summaryFailed: generated.length === 0,
  };
});

const pickCount = Math.min(cfg.topN, candidates.length);

const SYSTEM = `You are the editor of "Pixel Wires", a daily news digest for professional software developers.
From the candidates, choose the ${pickCount} best for today and order them, most important first.
Prefer a mix of sources and topics, and skip near-duplicates of the same story.
For each pick write one short line (at most 20 words) on why it matters to developers.
Also write a 2-3 sentence intro for today's digest that names the main themes. Plain text, no emojis, no markdown.
Answer only with JSON.`;

const list = candidates
  .map((post) =>
    [
      `id: ${post.id}`,
      `title: ${post.title}`,
      `source: ${post.source === 'devto' ? 'DEV' : 'Hacker News'} (${post.domain ?? 'unknown'})`,
      `quality: ${post.quality}/10`,
      `summary: ${post.digestSummary}`,
    ].join('\n'),
  )
  .join('\n\n');

const SCHEMA = {
  type: 'object',
  properties: {
    intro: { type: 'string', maxLength: 600 },
    picks: {
      type: 'array',
      minItems: pickCount,
      maxItems: pickCount,
      items: {
        type: 'object',
        properties: {
          id: { type: 'string', enum: candidates.map((post) => post.id) },
          why: { type: 'string', maxLength: 200 },
        },
        required: ['id', 'why'],
      },
    },
  },
  required: ['intro', 'picks'],
};

return [
  {
    json: {
      candidates,
      request: {
        model: cfg.models.editor,
        stream: false,
        think: false,
        keep_alive: '5m',
        format: SCHEMA,
        options: { temperature: 0.4, num_ctx: 16384 },
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: `Date: ${cfg.dateLabel}\n\nCandidates:\n\n${list}` },
        ],
      },
    },
  },
];

// Assemble the digest JSON the website reads (see src/types/digest.ts).
const cfg = $('Config').first().json;
const { candidates } = $('Build editor request').first().json;
const editorOutput = $input.first()?.json;

let editor = null;
try {
  editor = JSON.parse(editorOutput?.message?.content ?? '');
} catch {
  editor = null;
}

const byId = new Map(candidates.map((post) => [post.id, post]));
const chosen = [];
const used = new Set();

for (const pick of Array.isArray(editor?.picks) ? editor.picks : []) {
  const post = byId.get(pick?.id);
  if (!post || used.has(post.id)) continue;
  used.add(post.id);
  chosen.push({ post, why: typeof pick.why === 'string' ? pick.why.trim() : '' });
}

// If the editor returned too few valid picks, fill up by quality score.
for (const post of candidates) {
  if (chosen.length >= cfg.topN) break;
  if (used.has(post.id)) continue;
  used.add(post.id);
  chosen.push({ post, why: '' });
}

const items = chosen.slice(0, cfg.topN).map(({ post, why }, index) => ({
  rank: index + 1,
  summary: post.digestSummary,
  why: why || null,
  quality: post.quality,
  article: {
    id: post.id,
    source: post.source,
    nativeId: post.nativeId,
    title: post.title,
    summary: post.summary,
    url: post.url,
    domain: post.domain,
    discussionUrl: post.discussionUrl,
    coverImage: post.coverImage,
    tags: post.tags,
    author: post.author,
    publishedAt: post.publishedAt,
    readingTimeMinutes: post.readingTimeMinutes,
    score: post.score,
    commentCount: post.commentCount,
  },
}));

const intro =
  typeof editor?.intro === 'string' && editor.intro.trim().length > 0
    ? editor.intro.trim()
    : `Today's ${items.length} most useful posts for developers from DEV and Hacker News.`;

const digest = {
  version: 1,
  date: cfg.date,
  generatedAt: new Date().toISOString(),
  intro,
  items,
  stats: {
    fetched: candidates[0]?.fetchedCount ?? candidates.length,
    shortlisted: candidates.length,
    published: items.length,
    scoringFailures: candidates[0]?.scoringFailures ?? 0,
    summaryFailures: candidates.filter((post) => post.summaryFailed).length,
    editorFallback: editor === null,
  },
  models: cfg.models,
};

return [{ json: { digest } }];

// Files for the commit: today's digest, latest.json and the list of available dates.
const cfg = $('Config').first().json;
const { digest } = $('Build digest').first().json;
const MAX_DATES = 180;

let dates = [];
const existing = $input.first()?.json;
// A 404 on the first run is expected: the index doesn't exist yet.
if (existing && !existing.error && typeof existing.data === 'string') {
  try {
    const parsed = JSON.parse(existing.data);
    if (Array.isArray(parsed?.dates)) dates = parsed.dates.filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d));
  } catch {
    dates = [];
  }
}

dates = [cfg.date, ...dates.filter((d) => d !== cfg.date)].sort().reverse().slice(0, MAX_DATES);

const pretty = (value) => `${JSON.stringify(value, null, 2)}\n`;
const files = [
  { path: `public/digest/${cfg.date}.json`, content: pretty(digest) },
  { path: 'public/digest/latest.json', content: pretty(digest) },
  { path: 'public/digest/index.json', content: pretty({ version: 1, updatedAt: digest.generatedAt, dates }) },
];

const message = [
  `Daily digest ${cfg.date}`,
  '',
  `${digest.items.length} posts picked from ${digest.stats.fetched} by ${cfg.models.score}, ${cfg.models.summary} and ${cfg.models.editor}.`,
  'Generated by the n8n "Pixel Wires - Daily digest" workflow.',
].join('\n');

return [{ json: { files, message } }];

// The WhatsApp message: intro, every post's title, a "why it matters" line for the top
// ones, and a link to the full page with summaries.
const cfg = $('Config').first().json;
const { digest } = $('Build digest').first().json;
const commitSha = $('Create commit').first().json.sha;

const sourceLabel = { devto: 'DEV', hackernews: 'HN' };
const label = (item) => sourceLabel[item.article.source] ?? item.article.source;
const detailed = digest.items.slice(0, cfg.postsInWhatsApp);
const rest = digest.items.slice(cfg.postsInWhatsApp);

const lines = [`*Pixel Wires · Daily digest*`, `_${cfg.dateLabel}_`, '', digest.intro, ''];

// Top posts: title, one line on why it matters, link.
for (const item of detailed) {
  lines.push(`*${item.rank}. ${item.article.title}* (${label(item)})`);
  lines.push(item.why || item.summary);
  lines.push(item.article.url);
  lines.push('');
}

// The rest: title and link only, so the whole list is in the message.
if (rest.length > 0) {
  lines.push('*Also today*');
  for (const item of rest) {
    lines.push(`${item.rank}. ${item.article.title} (${label(item)})`);
    lines.push(item.article.url);
  }
  lines.push('');
}

const pageUrl = `${cfg.siteUrl.replace(/\/+$/, '')}/today/${cfg.date}`;
lines.push(`All ${digest.items.length} with summaries: ${pageUrl}`);
lines.push('_The page goes live about a minute after this message._');

return [
  {
    json: {
      chatId: `${cfg.whatsappTo}@c.us`,
      text: lines.join('\n'),
      // Same key on an automatic retry, so a retried send can't arrive twice.
      idempotencyKey: `pixelwire-digest-${cfg.date}-${String(commitSha).slice(0, 12)}`,
    },
  },
];
